css:
.frame .scene.reference-bookend.tcard{display:flex;align-items:center;justify-content:center;background:var(--theater);padding:0 80px}
.reference-bookend .tc{text-align:center;max-width:1120px}
.reference-bookend .tc-eyebrow{font-size:15px;letter-spacing:.22em;color:var(--em-400);font-weight:700;margin-bottom:18px;min-height:20px}
.reference-bookend .tc-title{font-size:52px;line-height:1.28;font-weight:800;color:#fff;margin:0;letter-spacing:.01em}
.reference-bookend .tc-sub{font-size:26px;line-height:1.5;color:var(--em-200);margin:18px 0 0;font-weight:500}
.reference-bookend .s11wrap{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;max-width:1040px;margin:6px auto 0}
.reference-bookend .s11{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.18);
       color:#fff;border-radius:999px;padding:10px 18px;font-size:18px;font-weight:600;white-space:nowrap}
.reference-bookend .s11 b{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;border-radius:50%;
         background:var(--em-500);color:#08201d;font-size:13px;font-weight:800}
.reference-bookend .end-title.op .op-line{font-size:32px;font-weight:700;color:#fff;line-height:1.5;margin:6px 0 0;letter-spacing:.01em}
.reference-bookend .end-title.op .op-line2{font-size:26px;font-weight:500;color:var(--em-200);margin-top:10px}
.reference-bookend .end-title.op .et-rule{margin:26px 0 22px}
.reference-bookend .gt{position:absolute;inset:0;padding:34px 70px 196px;display:flex;flex-direction:column;gap:12px;color:#fff}
.reference-bookend .gt-h{display:flex;align-items:center;justify-content:space-between}
.reference-bookend .gt-eyebrow{font-size:14px;letter-spacing:.24em;color:var(--em-300);font-weight:700}
.reference-bookend .gt-legend{font-size:14px;color:var(--theater-muted);display:flex;align-items:center;gap:6px}
.reference-bookend .gt-legend i{display:inline-block;width:14px;height:14px;border-radius:4px;margin-right:4px}
.reference-bookend .gt-legend i.ai{background:var(--em-500)}
.reference-bookend .gt-legend i.hu{background:#FF7A6B}
.reference-bookend .gt-lanes,.reference-bookend .gt-row{display:grid;grid-template-columns:262px 1fr;align-items:center}
.reference-bookend .gt-lanegrid{display:grid;grid-template-columns:repeat(11,1fr);gap:0 6px}
.reference-bookend .gt-lane{font-size:12px;color:var(--theater-muted);border-top:1px solid var(--theater-line);padding-top:6px;white-space:nowrap;overflow:hidden;min-width:0;text-overflow:ellipsis}
.reference-bookend .gt-lane i{font-style:normal;font-weight:800;color:var(--em-300);margin-right:6px;letter-spacing:.08em}
.reference-bookend .gt-rows{display:flex;flex-direction:column;gap:7px}
.reference-bookend .gt-row{height:38px}
.reference-bookend .gt-label{display:flex;align-items:center;gap:10px;font-size:17px;font-weight:600;white-space:nowrap}
.reference-bookend .gt-label b{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;border-radius:50%;
              background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.22);font-size:12px;font-weight:800}
.reference-bookend .gt-badge{font-size:11px;font-weight:800;color:#2b120e;background:#FF7A6B;border-radius:6px;padding:2px 7px;margin-left:2px}
.reference-bookend .gt-track{position:relative;height:30px;border-left:1px solid var(--theater-line)}
.reference-bookend .gt-track::before{content:"";position:absolute;left:0;right:0;top:50%;height:1px;background:rgba(255,255,255,.06)}
.reference-bookend .gt-bar{position:absolute;top:2px;bottom:2px;border-radius:7px;background:linear-gradient(90deg,var(--em-500),var(--em-400));
          box-shadow:0 4px 14px rgba(21,145,120,.35);transform:scaleX(0);transform-origin:left center;
          transition:transform .55s cubic-bezier(.2,.8,.2,1),opacity .3s}
.reference-bookend .gt-bar.cue{opacity:0;transform:scaleX(0)}
.reference-bookend .gt-bar.cue.in{opacity:1;transform:scaleX(1)}
.reference-bookend .gt-bar.human{background:linear-gradient(90deg,#FF7A6B,#FF9A8A);box-shadow:0 4px 16px rgba(255,111,97,.45);display:flex;align-items:center;justify-content:center}
.reference-bookend .gt-bar.human em{font-style:normal;font-size:12px;font-weight:800;color:#2b120e;white-space:nowrap}
.frame .scene.reference-bookend{background:transparent;transform:scale(1.012)!important;transition:opacity .6s var(--ease),transform .9s var(--ease)}
.frame .scene.reference-bookend.on{transform:none!important}
.frame .scene.reference-bookend.tcard{background:var(--theater)}
@media(prefers-reduced-motion:reduce){.frame .scene.reference-bookend{transition:none!important}}
